@php($seed = old('sections_json') ? json_decode(old('sections_json'),true) : ($landing->draft_sections ?? []))
<script>
(()=>{
const items=@json($seed ?: []), list=document.getElementById('sections-list'), hidden=document.getElementById('sections-json');
const csrf=document.querySelector('meta[name="csrf-token"]')?.content || document.querySelector('#aron-landing-editor input[name="_token"]').value;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const serialize=()=>hidden.value=JSON.stringify(items);
function render(){list.innerHTML='';items.forEach((s,i)=>{const el=document.createElement('article');el.className='rounded-2xl border border-slate-200 bg-white p-4 space-y-3';el.innerHTML=`<div class="flex flex-wrap items-center gap-2"><strong class="flex-1">${esc(s.type)} — ${i+1}</strong><label class="text-sm"><input type="checkbox" data-f="enabled" ${s.enabled!==false?'checked':''}> فعال</label><button type="button" data-action="up" class="rounded-lg border px-3 py-1">↑</button><button type="button" data-action="down" class="rounded-lg border px-3 py-1">↓</button><button type="button" data-action="remove" class="rounded-lg border px-3 py-1 text-rose-600">حذف</button></div><input class="a-input" placeholder="عنوان سکشن" data-f="title" value="${esc(s.title)}"><input class="a-input" placeholder="زیرعنوان" data-f="subtitle" value="${esc(s.subtitle)}"><textarea class="a-input" rows="3" placeholder="متن توضیحات" data-f="body">${esc(s.body)}</textarea><input class="a-input" placeholder="آدرس تصویر اصلی" data-f="image" value="${esc(s.image)}"><label class="block text-sm">آپلود تصویر <input type="file" accept="image/png,image/jpeg,image/webp" data-upload></label><textarea class="a-input" rows="4" data-f="items" placeholder="آیتم‌ها یا آدرس تصاویر گالری، هر مورد یک خط">${esc((s.items||[]).join('\n'))}</textarea><div class="grid sm:grid-cols-2 gap-2"><input class="a-input" data-f="button_text" placeholder="متن دکمه" value="${esc(s.button_text)}"><input class="a-input" data-f="button_url" placeholder="لینک دکمه" value="${esc(s.button_url)}"></div>`;
el.querySelectorAll('[data-f]').forEach(input=>input.addEventListener('input',()=>{s[input.dataset.f]=input.dataset.f==='enabled'?input.checked:input.dataset.f==='items'?input.value.split('\n').map(x=>x.trim()).filter(Boolean):input.value;serialize()}));
el.querySelectorAll('button[data-action]').forEach(b=>b.addEventListener('click',()=>{const action=b.dataset.action;if(action==='remove')items.splice(i,1);else{const target=i+(action==='up'?-1:1);if(target>=0&&target<items.length)[items[i],items[target]]=[items[target],items[i]];}render()}));
el.querySelector('[data-upload]').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;const body=new FormData();body.append('image',file);try{const r=await fetch(@json(route('panel.landing.upload')),{method:'POST',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json'},body});if(!r.ok)throw new Error('آپلود ناموفق بود');const result=await r.json();if(s.type==='gallery'){s.items=[...(s.items||[]),result.url]}else{s.image=result.url}render()}catch(err){alert(err.message)}});
list.append(el)});serialize()}
document.getElementById('section-add').addEventListener('click',()=>{items.push({type:document.getElementById('section-type').value,title:'',subtitle:'',body:'',image:'',items:[],enabled:true,button_text:'',button_url:''});render()});render();
})();
</script>
